+        box-shadow: none;
+      }
+
+      .skip-link,
+      .submit-button {
+        background: ButtonFace;
+        color: ButtonText;
+        border: 1px solid ButtonBorder;
+        box-shadow: none;
+      }
+
+      .helper-text,
+      .intro,
+      .message,
+      .eyebrow {
+        color: CanvasText;
