  <title>Consent Form</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-muted: #f8fafc;
      --text: #102033;
      --muted: #5b6b7f;
      --border: #c6d1de;
      --border-strong: #7c8ea3;
      --accent: #2357ff;
      --accent-strong: #1639b8;
      --danger: #b42318;
      --success: #166534;
      --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, #e8efff 0, rgba(232, 239, 255, 0) 38%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      background: var(--text);
      color: #fff;
      border-radius: 0.75rem;
      text-decoration: none;
      transform: translateY(-180%);
      transition: transform 0.2s ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #9db5ff;
      outline-offset: 2px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1.5rem;
    }

    .card {
      width: min(100%, 30rem);
      background: var(--surface);
      border: 1px solid rgba(198, 209, 222, 0.7);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 2rem;
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.75rem, 4vw, 2.25rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0.9rem 0 1.5rem;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      padding: 1rem;
      background: var(--surface-muted);
      border: 1px solid var(--border);
      border-radius: 1rem;
    }

    .checkbox-row {
      display: flex;
      align-items: flex-start;
      gap: 0.85rem;
    }

    input[type="checkbox"] {
      width: 1.15rem;
      height: 1.15rem;
      margin: 0.15rem 0 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    label {
      font-weight: 600;
      line-height: 1.5;
    }

    .required {
      color: var(--danger);
    }

    .helper-text,
    .message {
      margin: 0.6rem 0 0;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--muted);
    }

    .message {
      min-height: 1.5rem;
      font-weight: 600;
    }

    .message.error {
      color: var(--danger);
    }

    .message.success {
      color: var(--success);
    }

    .submit-button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.3rem;
      background: linear-gradient(135deg, var(--accent) 0%, #5d7cff 100%);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 0.16s ease, box-shadow 0.16s ease, background 0.16s ease;
      box-shadow: 0 16px 24px rgba(35, 87, 255, 0.24);
    }

    .submit-button:hover {
      transform: translateY(-1px);
      background: linear-gradient(135deg, var(--accent-strong) 0%, #4b67ee 100%);
    }

    .submit-button:focus-visible,
    input[type="checkbox"]:focus-visible {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 4px rgba(157, 181, 255, 0.9);
    }

    .form-field.invalid {
      border-color: var(--danger);
    }

    @media (max-width: 32rem) {
      .card {
        padding: 1.5rem;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
        color: CanvasText;
      }

      .card,
      .form-field {
        background: Canvas;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .skip-link,
      .submit-button {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .helper-text,
      .intro,
      .message,
      .eyebrow {
        color: CanvasText;
      }

      .submit-button:focus-visible,
      input[type="checkbox"]:focus-visible,
      .skip-link:focus {
        outline: 2px solid Highlight;
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Quick setup</p>
      <h1 id="page-title">Agree to the terms</h1>
      <p class="intro">Review your preference and confirm consent before continuing.</p>

      <form id="consent-form" novalidate>
        <div class="form-field" id="consent-field">
          <div class="checkbox-row">
            <input
              id="terms-consent"
              name="termsConsent"
              type="checkbox"
              required
              aria-describedby="consent-help consent-message"
            >
            <label for="terms-consent">
              I agree to the Terms of Use <span class="required" aria-hidden="true">*</span>
            </label>
          </div>
          <p class="helper-text" id="consent-help">Required to continue with your submission.</p>
        </div>

        <button class="submit-button" type="submit">Submit</button>
        <p class="message" id="consent-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('terms-consent');
    const field = document.getElementById('consent-field');
    const message = document.getElementById('consent-message');

    function showMessage(text, type) {
      message.textContent = text;
      message.className = `message ${type}`;
    }

    function syncValidity() {
      const invalid = !checkbox.checked;
      checkbox.setAttribute('aria-invalid', String(invalid));
      field.classList.toggle('invalid', invalid);
      return !invalid;
    }

    checkbox.addEventListener('change', () => {
      if (checkbox.checked) {
        showMessage('', '');
      }
      syncValidity();
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!syncValidity()) {
        showMessage('Please agree to the Terms of Use before submitting.', 'error');
        checkbox.focus();
        return;
      }

      showMessage('Thanks — your consent has been recorded.', 'success');
    });

    syncValidity();
  </script>
</body>
</html>
