  <script>
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('terms-consent');
    const field = document.getElementById('consent-field');
    const message = document.getElementById('consent-message');

    function showMessage(text, type) {
      message.textContent = text;
      message.className = `message ${type}`;
    }

    function syncValidity(showInvalid = false) {
      const invalid = !checkbox.checked;
      checkbox.setAttribute('aria-invalid', showInvalid && invalid ? 'true' : 'false');
      field.classList.toggle('invalid', showInvalid && invalid);
      return !invalid;
    }

    checkbox.addEventListener('change', () => {
      if (checkbox.checked) {
        showMessage('', '');
      }
      syncValidity(!checkbox.checked);
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!syncValidity(true)) {
        showMessage('Please agree to the Terms of Use before submitting.', 'error');
        checkbox.focus();
        return;
      }

      showMessage('Thanks — your consent has been recorded.', 'success');
    });

    syncValidity(false);
  </script>
